  ('456', 'edusmart_assignments_v1', 'asg-gr4-math-1', '{"id":"asg-gr4-math-1","grade":4,"stream":"Dove","subject":"Mathematics","title":"Practical Fraction Modeling with Household Items","instructions":"Divide a piece of fruit or paper into 8 equal parts. Photograph or write down three fractions you can create (e.g., 2/8, 4/8, 6/8) and simplify them.","dueDate":"2026-10-06","maxScore":20,"teacherName":"Mr. David Kiprono","teacherId":"usr-teach-kiprono","submissionsCount":4}'::jsonb, false),
