  ('456', 'edusmart_chat_messages_v1', 'msg-1', '{"id":"msg-1","senderId":"usr-teach-kiprono","senderName":"Mr. David Kiprono","senderRole":"class_teacher","grade":4,"stream":"Dove","message":"Good morning Grade 4 Dove scholars! Please ensure you have reviewed the Fractions notes before our 10:00 AM Google Meet session.","timestamp":"08:15 AM","isDirect":false}'::jsonb, false),
  ('456', 'edusmart_chat_messages_v1', 'msg-2', '{"id":"msg-2","senderId":"usr-stu-brian","senderName":"Brian Otieno","senderRole":"student","grade":4,"stream":"Dove","message":"Good morning Teacher Kiprono. We have reviewed Topic 2 and attempted the mental quiz.","timestamp":"08:22 AM","isDirect":false}'::jsonb, false),
  ('456', 'edusmart_chat_messages_v1', 'msg-3', '{"id":"msg-3","senderId":"usr-stu-brian","senderName":"Brian Otieno","senderRole":"student","grade":4,"recipientId":"usr-teach-kiprono","recipientName":"Mr. David Kiprono","message":"Teacher Kiprono, on Question 4 of the Fractions worksheet, when simplifying 6/8 do we divide by 2?","timestamp":"09:05 AM","isDirect":true}'::jsonb, false),
  ('456', 'edusmart_chat_messages_v1', 'msg-4', '{"id":"msg-4","senderId":"usr-teach-kiprono","senderName":"Mr. David Kiprono","senderRole":"class_teacher","grade":4,"recipientId":"usr-stu-brian","recipientName":"Brian Otieno","message":"Yes Brian! 6 divided by 2 is 3, and 8 divided by 2 is 4, which gives 3/4. Spot on!","timestamp":"09:12 AM","isDirect":true}'::jsonb, false),
