  ('456', 'edusmart_portfolio_v1', 'port-1', '{"id":"port-1","studentId":"usr-stu-brian","studentName":"Brian Otieno","grade":4,"subject":"Creative Arts","title":"Indigenous Sisal & Reeds Weaving Basket","description":"Constructed a traditional circular storage basket using dyed sisal fibers and dry reed strands found in local environment.","learningStrand":"Craft & Indigenous Material Manipulation","category":"Creative Arts & Craft","evidenceUrl":"https://images.unsplash.com/photo-1544816155-12df9643f363?w=500&auto=format&fit=crop&q=80","reflection":"I learned how to cross the warp and weft strands evenly so that the basket holds grains without spilling. It required patience and strong finger grip.","teacherFeedback":"Exemplary craftsmanship. Shows deep mastery of geometric symmetry and indigenous Kenyan craft techniques.","competencyLevel":"Exceeding Expectations","awardedPoints":50,"createdAt":"2026-09-26"}'::jsonb, false),
  ('456', 'edusmart_portfolio_v1', 'port-2', '{"id":"port-2","studentId":"usr-stu-brian","studentName":"Brian Otieno","grade":4,"subject":"Integrated Science","title":"Multi-Layer Soil & Sand Water Filtration Unit","description":"Designed and tested a mechanical water purifier using coarse gravel, fine sand, and activated charcoal layers inside a recycled container.","learningStrand":"Environmental Conservation & Living Things","category":"Experiment & Science","evidenceUrl":"https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=500&auto=format&fit=crop&q=80","reflection":"Filtered muddy rainwater from the school garden. The first output was slightly cloudy, but running it twice made it clear. Charcoal removed the odor.","teacherFeedback":"Outstanding scientific inquiry. Brian formulated a clear hypothesis and recorded accurate flow-rate observations.","competencyLevel":"Exceeding Expectations","awardedPoints":60,"createdAt":"2026-09-29"}'::jsonb, false),
  ('456', 'edusmart_portfolio_v1', 'port-3', '{"id":"port-3","studentId":"usr-stu-brian","studentName":"Brian Otieno","grade":4,"subject":"Agriculture and Nutrition","title":"Sukuma Wiki Container Garden Growth Log","description":"Planted collard greens in an upcycled sack filled with composted topsoil. Logged daily watering and weekly leaf growth.","learningStrand":"Crop Production & Food Security","category":"Project & Model","evidenceUrl":"https://images.unsplash.com/photo-1592417817098-8f3d69103a89?w=500&auto=format&fit=crop&q=80","reflection":"Practiced vertical gardening because it saves space. Mulching with dry grass helped keep the soil moist during hot afternoons.","teacherFeedback":"Very neat observational drawings and accurate growth measurements over 3 weeks.","competencyLevel":"Meeting Expectations","awardedPoints":45,"createdAt":"2026-09-22"}'::jsonb, false),
