  ('456', 'edusmart_sanatorium_records_v1', 'san-1', '{"id":"san-1","studentId":"usr-stu-sharon","studentName":"Sharon Cherono","admissionNumber":"ADM/2021/0812","grade":8,"stream":"Mara","parentName":"Grace Cherono (Mother)","parentPhone":"+254 711 445 892","nurseInCharge":"Sister Grace Wambui, RN","nurseLicenseNo":"NCK/RN-58921","nurseStaffNo":"SAN/002","date":"2026-10-02","arrivalTime":"10:15 AM","departureTime":"11:45 AM","visitReason":"High febrile illness with chills, dizziness, and body weakness","symptoms":["High Fever","Headache","Chills","Nausea"],"vitalSigns":{"temperature":38.8,"pulseRate":94,"bloodPressure":"110/72","respiratoryRate":20},"treatmentAdministered":"Paracetamol 500mg oral stat, cold sponge compression applied to forehead and axillae, oral rehydration solution (ORS) 300ml administered.","disposition":"signed_out_to_parent","bedNumber":"Observation Bed #01","recommendations":"Patient has high-grade fever unresponsive to mild antipyretics. Signed out to mother Grace Cherono for full laboratory malaria and typhoid diagnostic workup at Nairobi Hospital. 3 days medical leave recommended.","activityRestrictions":"Complete bed rest; exempt from physical education, practicals, and evening preps until Monday.","followUpPlan":"Parent to present medical discharge summary upon return to school.","parentNotified":true,"parentNotificationNotes":"Mother contacted at 10:40 AM; arrived at campus gate at 11:30 AM. Gate Pass #GP-8M-3310 dispatched.","gatePassId":"gep-2","recordedAt":"2026-10-02T10:15:00","recordedBy":"Sister Grace Wambui, RN"}'::jsonb, false),
  ('456', 'edusmart_sanatorium_records_v1', 'san-2', '{"id":"san-2","studentId":"usr-stu-kelvin","studentName":"Kelvin Kiprop","admissionNumber":"ADM/2023/0414","grade":4,"stream":"Dove","parentName":"Dr. Joseph Kiprop (Father)","parentPhone":"+254 722 891 042","nurseInCharge":"Sister Grace Wambui, RN","nurseLicenseNo":"NCK/RN-58921","nurseStaffNo":"SAN/002","date":"2026-10-02","arrivalTime":"08:45 AM","departureTime":"09:30 AM","visitReason":"Sports abrasion on right knee and contusion sustained during morning physical warm-up","symptoms":["Superficial laceration","Mild knee swelling","Localized pain"],"vitalSigns":{"temperature":36.8,"pulseRate":78,"bloodPressure":"105/68","respiratoryRate":18},"treatmentAdministered":"Antiseptic cleaning with saline, povidone-iodine dressing applied, sterile gauze bandage wrapped. Cold ice compression applied for 15 minutes.","disposition":"treated_returned_to_class","recommendations":"Wound is clean and sterile dressing is intact. Keep dressing dry. Safe to attend all academic lessons. Excused from high-impact running and football for 48 hours.","activityRestrictions":"No field sports or running until wound re-evaluated on Monday.","followUpPlan":"Report back to sanatorium on Monday 08:30 AM for dressing review.","parentNotified":true,"parentNotificationNotes":"SMS notification sent via EduSmart clinic gateway confirming minor knee dressing.","recordedAt":"2026-10-02T08:45:00","recordedBy":"Sister Grace Wambui, RN"}'::jsonb, false),
  ('456', 'edusmart_sanatorium_records_v1', 'san-3', '{"id":"san-3","studentId":"usr-stu-brian","studentName":"Brian Otieno","admissionNumber":"ADM/2023/0412","grade":4,"stream":"Dove","parentName":"Mary Otieno (Mother)","parentPhone":"+254 722 345 678","nurseInCharge":"Nurse David Ochieng, KRCHN","nurseLicenseNo":"NCK/RN-61402","nurseStaffNo":"SAN/005","date":"2026-10-03","arrivalTime":"09:10 AM","departureTime":"10:20 AM","visitReason":"Acute bronchial spasm / exercise-induced asthma tightness after morning sprint drill","symptoms":["Wheezing","Shortness of breath","Chest tightness"],"vitalSigns":{"temperature":36.6,"pulseRate":86,"bloodPressure":"108/70","respiratoryRate":24},"treatmentAdministered":"Salbutamol 100mcg (2 puffs via spacer device). Patient positioned upright in high Fowler''s. Peak flow measured at 280 L/min. Observed for 45 minutes until chest sounds cleared bilaterally.","disposition":"treated_returned_to_class","recommendations":"Bronchial spasm resolved; respiratory sounds clear bilaterally. Student carrying prescribed inhaler in school bag. Class teacher alerted to monitor during outdoor activities.","activityRestrictions":"Avoid cold morning outdoor activities and dusty field areas for remainder of day.","followUpPlan":"Return immediately if wheeze recurs; check-in before departure at 3:30 PM.","parentNotified":true,"parentNotificationNotes":"Parent informed via call; inhaler refill confirmed at home.","recordedAt":"2026-10-03T09:10:00","recordedBy":"Nurse David Ochieng, KRCHN"}'::jsonb, false),
  ('456', 'edusmart_sanatorium_records_v1', 'san-4', '{"id":"san-4","studentId":"usr-stu-faith","studentName":"Faith Wanjiru","admissionNumber":"ADM/2021/0811","grade":8,"stream":"Mara","parentName":"James Wanjiru (Father)","parentPhone":"+254 720 112 233","nurseInCharge":"Sister Grace Wambui, RN","nurseLicenseNo":"NCK/RN-58921","nurseStaffNo":"SAN/002","date":"2026-10-03","arrivalTime":"11:00 AM","departureTime":"01:30 PM","visitReason":"Throbbing frontal migraine and visual photophobia following computer lab session","symptoms":["Severe headache","Photophobia","Mild nausea"],"vitalSigns":{"temperature":37.1,"pulseRate":82,"bloodPressure":"118/76","respiratoryRate":18},"treatmentAdministered":"Ibuprofen 400mg with light snack and warm chamomile tea. Admitted to quiet dark recovery bay on Observation Bed #02.","disposition":"admitted_observation_bay","bedNumber":"Observation Bed #02","recommendations":"Learner placed under dark-room rest protocol. Avoid screen exposure, fluorescent lights, and loud noise. Re-evaluate after 90 minutes of sleep before clearing to return to dorm/class.","activityRestrictions":"Excused from afternoon computer practicals and physical education.","followUpPlan":"Check blood pressure and headache pain score at 1:30 PM.","parentNotified":true,"parentNotificationNotes":"Father notified that Faith is resting comfortably in sanatorium observation room.","recordedAt":"2026-10-03T11:00:00","recordedBy":"Sister Grace Wambui, RN"}'::jsonb, false),
