  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-001', '{"id":"cba-map-001","grade":4,"stream":"East","subject":"Mathematics","term":2,"academicYear":2026,"strand":"Numbers & Operations","subStrand":"Fractions & Equivalent Quantities","objectiveCode":"CBC-MAT-G4-O1","curriculumObjective":"Learner can divide concrete continuous quantities into fractional parts and compare equivalent values using physical models.","coreCompetency":"Critical Thinking & Problem Solving","bloomDomain":"Applying & Calculating","taskTitle":"Fraction Strip Construction & Equivalence Investigation","taskDescription":"Learners measure, fold, and color paper strips into halves, quarters, and eighths, verifying equivalence by direct superposition in paired classwork.","assessmentType":"Authentic Performance Task","assessmentCycle":"Continuous Assessment (CATs)","leadTeacherName":"Ms. Sarah Mwangi","weightagePercent":15,"rubricCriteria":[{"id":"rc-01","criterionTitle":"Precision in Fractional Division","eeDescriptor":"Accurately measures and folds strips into equal units; spontaneously discovers and explains 2/4 = 1/2 and 4/8 = 1/2.","meDescriptor":"Folds strips into equal units with minimal guidance and correctly identifies equivalent pairs.","aeDescriptor":"Requires teacher prompts to fold equal strips; partially identifies equivalent pairs.","beDescriptor":"Struggles to form equal divisions without continuous one-on-one assistance."},{"id":"rc-02","criterionTitle":"Mathematical Communication & Justification","eeDescriptor":"Articulates clear rationale using fractional notation and relates to real-life sharing scenarios.","meDescriptor":"Uses correct fraction terms (numerator, denominator) to explain equivalence.","aeDescriptor":"Names basic fractions but struggles to explain why 2/4 is equal to 1/2.","beDescriptor":"Unable to label fractional components without reference cards."}],"alignmentStatus":"verified","alignmentScore":96,"attainmentDistribution":{"eeCount":14,"meCount":22,"aeCount":5,"beCount":1,"totalLearners":42},"coordinatorNotes":"Fully aligned to KICD Grade 4 Curriculum Designs. Excellent formative rubric incorporating core competency.","lastVerifiedBy":"Mrs. Beatrice Omari (Curriculum Coordinator)","lastVerifiedAt":"2026-10-08T11:30:00Z","createdAt":"2026-10-01T08:00:00Z"}'::jsonb, false),
  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-002', '{"id":"cba-map-002","grade":4,"stream":"all","subject":"Integrated Science","term":2,"academicYear":2026,"strand":"Living Things & Ecosystems","subStrand":"Plant Nutrition & Water Transport","objectiveCode":"CBC-SCI-G4-O2","curriculumObjective":"Investigate the uptake and transport of colored water through plant stems using celery or white flowers.","coreCompetency":"Critical Thinking & Problem Solving","bloomDomain":"Analyzing & Deconstructing","taskTitle":"Xylem Capillary Action Laboratory Experiment & Observation Journal","taskDescription":"Small group setup: immerse celery stalks in red and blue food dye solutions, record hourly observations, dissect cross-sections to trace colored vascular bundles.","assessmentType":"Practical Lab Experiment","assessmentCycle":"Continuous Assessment (CATs)","leadTeacherName":"Mr. David Omondi","weightagePercent":20,"rubricCriteria":[{"id":"rc-03","criterionTitle":"Experimental Setup & Hygiene","eeDescriptor":"Sets up apparatus independently with pristine controls; measures dye dilution systematically.","meDescriptor":"Follows lab safety procedures and sets up colored water tubes accurately.","aeDescriptor":"Spills solution or cuts stalk unevenly; needs minor peer assistance.","beDescriptor":"Does not follow lab safety or experimental sequence."},{"id":"rc-04","criterionTitle":"Cross-Section Analysis & Drawing","eeDescriptor":"Produces labelled diagram showing colored xylem vessels with precise anatomical notes.","meDescriptor":"Identifies colored dots in cross-section and links to water transport.","aeDescriptor":"Draws general celery stalk without pinpointing vascular bundles.","beDescriptor":"Leaves journal entry incomplete or incorrect."}],"alignmentStatus":"verified","alignmentScore":92,"attainmentDistribution":{"eeCount":11,"meCount":25,"aeCount":6,"beCount":2,"totalLearners":44},"coordinatorNotes":"Integrated Science lab criteria conforms to KICD inquiry-based learning principles.","lastVerifiedBy":"Mrs. Beatrice Omari (Curriculum Coordinator)","lastVerifiedAt":"2026-10-09T09:15:00Z","createdAt":"2026-10-02T10:00:00Z"}'::jsonb, false),
  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-003', '{"id":"cba-map-003","grade":7,"stream":"West","subject":"Computer Studies","term":2,"academicYear":2026,"strand":"Computational Thinking & Algorithms","subStrand":"Scratch Block-Based Programming","objectiveCode":"CBC-CS-G7-O1","curriculumObjective":"Design and implement an interactive digital story or animation incorporating conditional logic, variable counters, and broadcast messages.","coreCompetency":"Digital Literacy","bloomDomain":"Creating & Designing","taskTitle":"Interactive Traffic Light & Pedestrian Safety Animation in Scratch","taskDescription":"Learners write Scratch block algorithms where user pressing spacebar changes light sequence and broadcasts message to animate pedestrian walking.","assessmentType":"Digital Coding Project","assessmentCycle":"CAT 1","leadTeacherName":"Mr. John Kamau","weightagePercent":25,"rubricCriteria":[{"id":"rc-05","criterionTitle":"Algorithmic Sequence & Conditional Logic","eeDescriptor":"Implements nested if-else loops, costume switches with zero glitching, and custom sound triggers.","meDescriptor":"Successfully programs sequential lights and triggers sprite movement via broadcast.","aeDescriptor":"Code executes but light timing is erratic or broadcast message triggers incorrect sprite.","beDescriptor":"Incomplete block arrangement with script errors preventing execution."},{"id":"rc-06","criterionTitle":"Creative Synthesis & User Experience","eeDescriptor":"Adds custom backdrop, audio cues, and pedestrian accessibility features.","meDescriptor":"Creates clean visual interface adhering to road safety guidelines.","aeDescriptor":"Functional but lacks proper scaling or clear visual indicators.","beDescriptor":"Uses default scratch cat with no road safety thematic assets."}],"alignmentStatus":"verified","alignmentScore":98,"attainmentDistribution":{"eeCount":16,"meCount":18,"aeCount":4,"beCount":0,"totalLearners":38},"coordinatorNotes":"Exemplary alignment with Junior Secondary Computer Studies syllabus. Project tested in Scratch Computer Lab.","lastVerifiedBy":"Mrs. Beatrice Omari (Curriculum Coordinator)","lastVerifiedAt":"2026-10-07T14:20:00Z","createdAt":"2026-10-03T11:00:00Z"}'::jsonb, false),
