  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-005', '{"id":"cba-map-005","grade":5,"stream":"North","subject":"Creative Arts","term":2,"academicYear":2026,"strand":"Visual Arts & Craft","subStrand":"Weaving & Pattern Construction","objectiveCode":"CBC-ART-G5-O1","curriculumObjective":"Construct a simple cardboard loom and weave functional placemat incorporating traditional Kenyan geometric motifs and indigenous plant fibers.","coreCompetency":"Imagination & Creativity","bloomDomain":"Creating & Designing","taskTitle":"Indigenous Fiber Loom Weaving & Cultural Motif Portfolio","taskDescription":"Learners prepare sisal or banana fiber yarns, string warp threads on notched cardboard, and weave alternating weft patterns reflecting indigenous cultural designs.","assessmentType":"Authentic Performance Task","assessmentCycle":"Continuous Assessment (CATs)","leadTeacherName":"Mr. Patrick Mutiso","weightagePercent":20,"rubricCriteria":[{"id":"rc-09","criterionTitle":"Loom Warping & Tension Uniformity","eeDescriptor":"Tension across all warp strings is impeccably uniform; edge selvages remain straight and parallel.","meDescriptor":"Warp strings are secure with consistent tension throughout.","aeDescriptor":"Uneven tension causes wavering borders in first half of placemat.","beDescriptor":"Cardboard loom warps or tears due to excessive pulling."},{"id":"rc-10","criterionTitle":"Cultural Motif Integration & Finishing","eeDescriptor":"Integrates two-tone contrasting geometric pattern inspired by local heritage; secures fringe knots neatly.","meDescriptor":"Uses complementary colored yarns and completes secure fringe finish.","aeDescriptor":"Pattern is disorganized; fringe ends untied.","beDescriptor":"Incomplete weave with fewer than 5 cm executed."}],"alignmentStatus":"needs_remediation","alignmentScore":72,"attainmentDistribution":{"eeCount":6,"meCount":18,"aeCount":12,"beCount":4,"totalLearners":40},"coordinatorNotes":"Pacing lag noted in syllabus radar. Assessment rubri