  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-007', '{"id":"cba-map-007","grade":6,"stream":"all","subject":"Agriculture","term":2,"academicYear":2026,"strand":"Crop Production & Environmental Conservation","subStrand":"Kitchen Garden & Container Gardening","objectiveCode":"CBC-AGR-G6-O1","curriculumObjective":"Construct multi-storey sack gardens using recycled materials and organic compost to optimize food production in limited spaces.","coreCompetency":"Citizenship","bloomDomain":"Psychomotor & Practical Execution","taskTitle":"Multi-Storey Vertical Sack Garden Construction & Drip Irrigation Trial","taskDescription":"Outdoor class project: perforate and layer gunny sacks with central gravel core for water percolation, transplant indigenous vegetable seedlings (managu, terere).","assessmentType":"Authentic Performance Task","assessmentCycle":"Continuous Assessment (CATs)","leadTeacherName":"Mr. Samuel Kibet","weightagePercent":20,"rubricCriteria":[{"id":"rc-13","criterionTitle":"Gravel Column Core Construction","eeDescriptor":"Builds flawless vertical gravel percolation core with perforated tin canister; soil compost mix is friable and rich.","meDescriptor":"Correctly places central gravel column and compacts soil firmly.","aeDescriptor":"Gravel column collapses or shifts off-center during soil filling.","beDescriptor":"Fills sack with unamended clay soil without drainage column."},{"id":"rc-14","criterionTitle":"Seedling Spacing & Water Conservation","eeDescriptor":"Spaces holes staggered at 15cm intervals; installs simple recycled bottle drip irrigation.","meDescriptor":"Transplants healthy seedlings without root trauma and moistens bed.","aeDescriptor":"Punctures sack holes too close together causing tearing.","beDescriptor":"Damages seedling roots during transplanting."}],"alignmentStatus":"verified","alignmentScore":95,"attainmentDistribution":{"eeCount":15,"meCount":21,"aeCount":4,"beCount":0,"totalLearners":40},"coordinatorNotes":"Outstanding practical application linking food security and environmental conservation.","lastVerifiedBy":"Mrs. Beatrice Omari (Curriculum Coordinator)","lastVerifiedAt":"2026-10-10T10:45:00Z","createdAt":"2026-10-06T08:15:00Z"}'::jsonb, false),
