  ('456', 'edusmart_cba_task_mappings_v1', 'cba-map-009', '{"id":"cba-map-009","grade":8,"stream":"all","subject":"Integrated Science","term":2,"academicYear":2026,"strand":"Matter & Chemical Reactions","subStrand":"Acids, Bases & Natural Indicators","objectiveCode":"CBC-SCI-G8-O4","curriculumObjective":"Extract natural acid-base indicators from hibiscus petals and red cabbage, and test everyday household substances (lemon juice, soap, ash water, vinegar).","coreCompetency":"Critical Thinking & Problem Solving","bloomDomain":"Analyzing & Deconstructing","taskTitle":"Natural Plant Indicator Extraction & pH Classification Lab","taskDescription":"Learners boil crushed hibiscus petals in hot water, filter filtrate into spotting tiles, observe distinct color shifts with acidic and basic test reagents.","assessmentType":"Practical Lab Experiment","assessmentCycle":"Mid-Term Evaluation","leadTeacherName":"Mr. David Omondi","weightagePercent":20,"rubricCriteria":[{"id":"rc-16","criterionTitle":"Safe Chemical Reagent Handling","eeDescriptor":"Zero contamination across test wells; systematically cleans droppers between acid and alkali samples.","meDescriptor":"Accurately tests each substance with fresh indicator without spillage.","aeDescriptor":"Contaminates one test well by dipping used dropper into reagent bottle.","beDescriptor":"Disregards safety instructions or consumes edible test materials."},{"id":"rc-17","criterionTitle":"Tabulation & Color Classification","eeDescriptor":"Constructs precise multi-column data table grouping items into strong acid, weak acid, neutral, and base.","meDescriptor":"Correctly classifies lemon juice as acid and wood ash as base.","aeDescriptor":"Records color changes but confuses which color represents acid vs base.","beDescriptor":"Leaves lab classification table blank."}],"alignmentStatus":"verified","alignmentScore":97,"attainmentDistribution":{"eeCount":14,"meCount":21,"aeCount":4,"beCount":1,"totalLearners":40},"coordinatorNotes":"Excellently structured Junior Secondary science practical. Natural indicators reduce reagent expense while teaching genuine chemistry principles.","lastVerifiedBy":"Mrs. Beatrice Omari (Curriculum Coordinator)","lastVerifiedAt":"2026-10-10T12:00:00Z","createdAt":"2026-10-06T14:00:00Z"}'::jsonb, false),
