  ('456', 'edusmart_curriculum_written_reports_v1', 'c-rep-002', '{"id":"c-rep-002","title":"CBA Formative Moderation & Attainment Consistency Analysis across Streams","reportType":"CBA Moderation & Attainment","targetGrade":4,"term":2,"academicYear":2026,"authorName":"Mrs. Beatrice Omari","authorRole":"Curriculum Coordinator","executiveSummary":"Comparative study across Grades 4 East, West, North, and South streams on competency-based assessment attainment tiers (EE, ME, AE, BE). Moderation reveals strong consistency in meeting expectations.","keyFindings":["28.4% of cohort achieved Exceeding Expectations (EE) in hands-on mathematical problem-solving.","56.2% consistently Met Expectations (ME), adhering closely to KICD standard benchmarks.","Approaching Expectations (AE) reduced from 18% in Term 1 to 12.1% in Term 2 following peer-mentoring groups.","Below Expectations (BE) learners identified for targeted scaffolding in decimal notation and fraction conversion."],"recommendations":["Maintain continuous portfolio artifact collection for all borderline AE learners.","Share Ms. Mwangi''s fraction strip manipulative rubric as best practice model across all primary streams."],"qualitativeComments":[{"id":"comm-03","author":"Mrs. Beatrice Omari","authorRole":"Curriculum Coordinator","comment":"All report card qualitative remarks across Grade 4 have been moderated and endorsed with curriculum stamps.","createdAt":"2026-10-09T10:00:00Z"}],"status":"published","createdAt":"2026-10-08T12:00:00Z","publishedAt":"2026-10-09T15:30:00Z"}'::jsonb, false),
